import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { buildHandProp, HandProp } from './models';
import type { ClothingItem } from './types';

/**
 * The mascot chef player, loaded from public/models/chef/chef.glb
 * (generated by tools/chef/buildChef.ts). Plays the skeletal clips with
 * crossfades, drives the facial blend shapes and holds tools and the tray.
 */

export type ChefExpression = 'jolly' | 'delighted' | 'focused' | 'surprised';

export interface ChefState {
  dt: number;
  moving: boolean;
  carrying: boolean;
  /** Tool to hold while cooking, or null when not cooking. */
  cookProp: HandProp | null;
  expression: ChefExpression;
}

export interface ChefRig {
  root: THREE.Group;
  mixer: THREE.AnimationMixer;
  actions: Record<string, THREE.AnimationAction>;
  current: string;
  faces: THREE.Mesh[];
  morph: Record<string, number>;
  blinkT: number;
  serveT: number;
  surpriseT: number;
  head: THREE.Object3D;
  rSocket: THREE.Object3D;
  lSocket: THREE.Object3D;
  toque: THREE.Object3D;
  kerchief: THREE.Object3D;
  buttons: THREE.Object3D;
  mats: Record<'jacket' | 'trousers' | 'shoes' | 'kerchief', THREE.MeshStandardMaterial>;
  props: Partial<Record<HandProp, THREE.Object3D>>;
}

const EXPRS = ['Smile', 'Laugh', 'Focused', 'Surprised'] as const;
const FADE = 0.22;
/** Clip speed so the feet keep pace with the game's 6.6 m/s movement. */
const TIME_SCALE: Record<string, number> = { Run: 1.05, CarryWalk: 1.5, Walk: 1.4 };

function assetBase(): string {
  try {
    return (import.meta as unknown as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? '/';
  } catch {
    return '/';
  }
}

let cached: Promise<THREE.Group & { userData: { clips: THREE.AnimationClip[] } }> | null = null;

export function loadChefRig(): Promise<ChefRig> {
  if (!cached) {
    cached = new GLTFLoader().loadAsync(`${assetBase()}models/chef/chef.glb`).then((gltf) => {
      gltf.scene.userData.clips = gltf.animations;
      return gltf.scene as THREE.Group & { userData: { clips: THREE.AnimationClip[] } };
    });
  }
  return cached.then((scene) => makeRig(scene, scene.userData.clips));
}

function makeRig(scene: THREE.Group, clips: THREE.AnimationClip[]): ChefRig {
  const faces: THREE.Mesh[] = [];
  const byName: Record<string, THREE.Object3D> = {};
  scene.traverse((o) => {
    byName[o.name] = o;
    const m = o as THREE.Mesh;
    if (!m.isMesh) return;
    m.frustumCulled = false; // skinned: bounds follow the bind pose, not the animation
    m.castShadow = m.name.startsWith('Body_');
    m.receiveShadow = false;
    if (m.morphTargetDictionary) faces.push(m);
  });
  const mat = (n: string) => (byName[n] as THREE.Mesh).material as THREE.MeshStandardMaterial;
  const mixer = new THREE.AnimationMixer(scene);
  const actions: Record<string, THREE.AnimationAction> = {};
  for (const c of clips) {
    if (c.name.startsWith('Face_')) continue;
    const a = mixer.clipAction(c);
    a.timeScale = TIME_SCALE[c.name] ?? 1;
    if (c.name === 'Serve') {
      a.setLoop(THREE.LoopOnce, 1);
      a.clampWhenFinished = true;
    }
    actions[c.name] = a;
  }
  actions.Idle.play();
  return {
    root: scene,
    mixer,
    actions,
    current: 'Idle',
    faces,
    morph: { Smile: 0, Laugh: 0, Focused: 0, Surprised: 0 },
    blinkT: 2,
    serveT: 0,
    surpriseT: 0,
    head: byName.Head,
    rSocket: byName.R_HandSocket,
    lSocket: byName.L_HandSocket,
    toque: byName.Body_Toque,
    kerchief: byName.Body_Neckerchief,
    buttons: byName.Body_Buttons,
    mats: { jacket: mat('Body_Jacket'), trousers: mat('Body_Trousers'), shoes: mat('Body_Shoes'), kerchief: mat('Body_Neckerchief') },
    props: {},
  };
}

function play(rig: ChefRig, name: string, restart = false) {
  if (rig.current === name && !restart) return;
  const next = rig.actions[name];
  if (!next) return;
  next.reset();
  next.setEffectiveWeight(1);
  next.fadeIn(FADE).play();
  // Fade out every other clip still contributing, so no old walk cycle lingers in the blend
  for (const [k, a] of Object.entries(rig.actions)) if (k !== name && a.isRunning()) a.fadeOut(FADE);
  rig.current = name;
}

/** Plays the one-shot serving animation (lean in, set the plate down, nod). */
export function triggerChefServe(rig: ChefRig) {
  rig.serveT = rig.actions.Serve ? rig.actions.Serve.getClip().duration : 0;
  play(rig, 'Serve', true);
}

/** A short surprised face (eyes wide, brows up). */
export function triggerChefSurprise(rig: ChefRig, seconds = 1.1) {
  rig.surpriseT = seconds;
}

export function updateChefRig(rig: ChefRig, s: ChefState) {
  const { dt } = s;
  if (rig.serveT > 0 && !s.moving) {
    rig.serveT -= dt;
  } else {
    rig.serveT = 0;
    const clip = s.carrying ? (s.moving ? 'CarryWalk' : 'CarryIdle') : s.moving ? 'Run' : s.cookProp ? 'Cook' : 'Idle';
    play(rig, clip);
  }
  rig.mixer.update(dt);

  // Hand tool while cooking
  const want = rig.current === 'Cook' ? s.cookProp : null;
  for (const [k, o] of Object.entries(rig.props)) if (o) o.visible = k === want;
  if (want && !rig.props[want]) {
    const o = buildHandProp(want);
    o.traverse((m) => ((m as THREE.Mesh).isMesh ? ((m as THREE.Mesh).castShadow = true) : null));
    rig.props[want] = o;
    rig.rSocket.add(o);
  }

  // Facial blend shapes
  rig.surpriseT = Math.max(0, rig.surpriseT - dt);
  const expr: ChefExpression = rig.surpriseT > 0 ? 'surprised' : s.expression;
  const target: Record<string, number> = {
    Smile: expr === 'jolly' ? 0.55 : 0,
    Laugh: expr === 'delighted' ? 1 : 0,
    Focused: expr === 'focused' ? 0.9 : 0,
    Surprised: expr === 'surprised' ? 1 : 0,
  };
  for (const k of EXPRS) rig.morph[k] = THREE.MathUtils.damp(rig.morph[k], target[k], 9, dt);
  rig.blinkT -= dt;
  if (rig.blinkT < 0) rig.blinkT = 2.4 + Math.random() * 2.6;
  const blink = rig.blinkT < 0.15 && rig.morph.Laugh < 0.5 ? Math.sin((rig.blinkT / 0.15) * Math.PI) : 0;
  for (const f of rig.faces) {
    const d = f.morphTargetDictionary!;
    const inf = f.morphTargetInfluences!;
    for (const k of EXPRS) if (d[k] !== undefined) inf[d[k]] = rig.morph[k];
    if (d.Blink !== undefined) inf[d.Blink] = blink;
  }
}

const _a = new THREE.Vector3();
const _b = new THREE.Vector3();
/** Midpoint between the hands, in `space`'s local coordinates (where the tray sits). */
export function chefCarryPoint(rig: ChefRig, space: THREE.Object3D, out: THREE.Vector3) {
  rig.rSocket.getWorldPosition(_a);
  rig.lSocket.getWorldPosition(_b);
  out.addVectors(_a, _b).multiplyScalar(0.5);
  return space.worldToLocal(out);
}

/** Shop outfit colours on the chef. The mascot's toque stays for the toque and "no hat" choices. */
export function applyChefOutfit(rig: ChefRig, outfit: ClothingItem, hat: ClothingItem, hatAnchor: THREE.Object3D) {
  rig.mats.jacket.color.set(outfit.hasSuit ? outfit.shirtColor ?? '#2b2b33' : outfit.shirtColor ?? '#f8f4ec');
  rig.mats.trousers.color.set(outfit.pantsColor ?? '#4a403b');
  rig.mats.shoes.color.set(outfit.shoeColor ?? '#4a2f22');
  rig.kerchief.visible = true;
  rig.mats.kerchief.color.set(outfit.scarfColor ?? outfit.vestColor ?? outfit.apronColor ?? (outfit.hasSuit ? outfit.trimColor ?? '#e5e7eb' : '#b8230e'));
  rig.buttons.visible = !outfit.hasSuit || Boolean(outfit.trimColor);
  const style = hat.hatStyle ?? 'none';
  const ownHat = style !== 'toque' && style !== 'none';
  rig.toque.visible = !ownHat;
  hatAnchor.visible = ownHat;
  if (hatAnchor.parent !== rig.head) rig.head.add(hatAnchor);
  // The bone sits at the neck; the crown of the big head is ~0.47 m above it
  hatAnchor.position.set(0, 0.43, -0.01);
  hatAnchor.rotation.set(0, 0, 0);
  hatAnchor.scale.setScalar(1.22);
}
